<?php
declare(strict_types=1);
require_once __DIR__ . '/app.php';
$token = trim((string)($_GET['token'] ?? ''));
if (!preg_match('/\A[a-f0-9]{24}\z/', $token)) { http_response_code(404); exit('This room page is not available.'); }
$stmt = db()->prepare('SELECT r.name, i.path FROM rooms r LEFT JOIN room_images i ON i.room_id=r.id WHERE r.public_token=? AND r.public_expires_at > UTC_TIMESTAMP() ORDER BY i.id');
$stmt->execute([$token]); $rows = $stmt->fetchAll();
if (!$rows) { http_response_code(404); exit('This room page is not available.'); }
$name = $rows[0]['name']; $images = array_values(array_filter(array_column($rows, 'path')));
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#26715d"><meta name="robots" content="noindex,nofollow"><title><?=h($name)?></title><link rel="manifest" href="manifest.webmanifest"><link rel="apple-touch-icon" href="icons/icon-192.png"><link rel="stylesheet" href="style.css"><script defer src="pwa.js"></script><?php if($images): ?><script defer src="photo-preview.js"></script><?php endif; ?></head><body><header class="topbar public-topbar"><span class="brand"><span class="brand-mark">S</span><span>staybook<small>ROOM GALLERY</small></span></span></header><main class="public-gallery"><div class="eyebrow">ROOM CATEGORY</div><h1><?=h($name)?></h1><?php if($images): ?><div class="public-photo-grid"><?php foreach($images as $image): ?><button class="public-photo-button" type="button" data-preview-image="<?=h($image)?>" data-preview-alt="<?=h($name)?>"><img src="<?=h($image)?>" alt="<?=h($name)?>"><span class="sr-only">View full image</span></button><?php endforeach; ?></div><?php else: ?><div class="empty public-empty"><div class="empty-icon">▧</div><h3>No photos yet</h3></div><?php endif; ?><footer>Shared room gallery</footer></main><?php if($images): ?><dialog class="photo-preview" aria-label="Image preview"><button class="photo-preview-close" type="button" aria-label="Close image preview">×</button><img class="photo-preview-image" alt=""><p class="photo-preview-caption"></p></dialog><?php endif; ?></body></html>
